import time
from azure.core.exceptions import HttpResponseError

try:
    result = client.get_status(operation_id)
except {{exception_type}} as exc:
    if exc.status_code != {{status_code}}:
        raise
    # This service contract supplies Retry-After as nonnegative seconds.
    raw = exc.response.headers.get("{{retry_header}}")
    try:
        delay = float(raw) if raw is not None else 1.0
    except (TypeError, ValueError):
        raise exc
    if not (0 <= delay <= remaining_retry_budget_seconds):
        raise  # defer the operation; do not retry before the server permits
    time.sleep(delay)
    # One retry only; its exceptions propagate to the caller.
    result = client.get_status(operation_id)

stream = openai.{{response_collection}}.create(
    extra_body={
        "agent_reference": {
            "name": agent_name,
            "type": "agent_reference",
        }
    },
    input="Explain the repair in one paragraph.",
    {{stream_parameter}}=True,
)

for event in stream:
    if event.type == "response.output_text.delta":
        print(event.{{delta_property}}, end="", flush=True)

